    { id = 6582, name = "The Test of Skulls, Scryer", level = 60, minLevel = 58, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, steps = { { name = "The Skull of Scryer", area = 618, x = 52.7, y = 55.9, mobs = { "Scryer" } } }, objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring." },
    { id = 6583, name = "The Test of Skulls, Somnus", level = 60, minLevel = 58, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, steps = { { name = "The Skull of Somnus", area = 8, x = 76.0, y = 66.6, mobs = { "Somnus" } } }, objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife." },
    { id = 6584, name = "The Test of Skulls, Chronalis", level = 60, minLevel = 58, requires = { 6570 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, steps = { { name = "The Skull of Chronalis", area = 440, x = 64.2, y = 48.5, mobs = { "Chronalis" } } }, objective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife." },
    { id = 6585, name = "The Test of Skulls, Axtroz", level = 60, minLevel = 60, requires = { 6582, 6583, 6584 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, steps = { { name = "The Skull of Axtroz", area = 11, x = 81.8, y = 48.2, mobs = { "Axtroz" } } }, objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." },
    { id = 6601, name = "Ascension...", level = 60, minLevel = 60, requires = { 6585 }, faction = "Horde", giver = "Emberstrife", start = { npc = "Emberstrife", area = 15, x = 56.7, y = 87.7 }, finish = { npc = "Rokaro", area = 405, x = 25.6, y = 70.0 }, objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rokaro and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." },
