    { id = 836, name = "Rescue OOX-09/HL!", level = 48, minLevel = 43, requires = { 485 }, giver = "Homing Robot OOX-09/HL", start = { npc = "Homing Robot OOX-09/HL", area = 47, x = 49.4, y = 37.7 }, finish = { npc = "Oglethorpe Obnoticus", area = 33, x = 28.4, y = 76.4 }, steps = { { name = "Escort OOX-09/HL to the shoreline beyond Overlook Cliff", area = 47, x = 79.1, y = 61.4 } }, objective = "Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay." },
