    { id = 2742, name = "Rin'ji is Trapped!", level = 47, minLevel = 42, faction = "Horde", giver = "Rin'ji", start = { npc = "Rin'ji", area = 47, x = 30.7, y = 46.9 }, finish = { npc = "Rin'ji's Secret", area = 47, x = 86.3, y = 59.0 }, steps = { { name = "Escort Rin'ji to safety", area = 47, x = 34.6, y = 56.3 } }, objective = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east." },
    { id = 2782, name = "Rin'ji's Secret", level = 47, minLevel = 45, requires = { 2742 }, faction = "Horde", giver = "Rin'ji's Secret", start = { npc = "Rin'ji's Secret", area = 47, x = 86.3, y = 59.0 }, finish = { npc = "Oran Snakewrithe", area = 1497, x = 73.1, y = 32.9 }, objective = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity." },
