    { id = 2881, name = "Troll Necklace Bounty (2/2)", level = 45, minLevel = 43, requires = { 2880 }, faction = "Alliance", giver = "Fraggar Thundermantle", start = { npc = "Fraggar Thundermantle", area = 47, x = 14.8, y = 44.6 }, finish = { npc = "Fraggar Thundermantle", area = 47, x = 14.8, y = 44.6 }, steps = { { name = "Troll Tribal Necklace", area = 47, x = 63.5, y = 74.1, mobs = { "Vilebranch Aman'zasi Guard", "Vilebranch Blood Drinker", "Vilebranch Scalper", "Vilebranch Soothsayer" } } } },
    { id = 2932, name = "Grim Message", level = 42, minLevel = 35, faction = "Horde", giver = "Nimboya", start = { npc = "Nimboya", area = 33, x = 32.2, y = 27.7 }, finish = { npc = "Nimboya", area = 33, x = 32.2, y = 27.7 }, steps = { { name = "Place the grim message.", area = 47, x = 23.4, y = 58.1 } }, objective = "Gather Witherbark Skulls and place on Nimboya's Pike. Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn." },
    { id = 2933, name = "Venom Bottles", level = 43, minLevel = 41, faction = "Horde", giver = "Venom Bottle", start = { npc = "Venom Bottle", area = 47, x = 23.5, y = 58.8 }, finish = { npc = "Apothecary Lydon", area = 267, x = 61.4, y = 19.1 }, objective = "Bring a Venom Bottle to an apothecary in Tarren Mill." },
    { id = 2934, name = "Undamaged Venom Sac", level = 45, minLevel = 40, requires = { 2933 }, faction = "Horde", giver = "Apothecary Lydon", start = { npc = "Apothecary Lydon", area = 267, x = 61.4, y = 19.1 }, finish = { npc = "Apothecary Lydon", area = 267, x = 61.4, y = 19.1 }, steps = { { name = "Undamaged Venom Sac", area = 47, x = 33.6, y = 70.1, mobs = { "Witherbark Broodguard" } } }, objective = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill." },
    { id = 2935, name = "Consult Master Gadrin", level = 45, minLevel = 43, requires = { 2934 }, faction = "Horde", giver = "Apothecary Lydon", start = { npc = "Apothecary Lydon", area = 267, x = 61.4, y = 19.1 }, finish = { npc = "Master Gadrin", area = 14, x = 56.0, y = 74.7 }, objective = "Speak with Master Gadrin in Sen'jin Village." },
    { id = 2937, name = "Summoning Shadra", level = 55, minLevel = 40, requires = { 2936 }, faction = "Horde", giver = "Master Gadrin", start = { npc = "Master Gadrin", area = 14, x = 56.0, y = 74.7 }, finish = { npc = "Apothecary Lydon", area = 267, x = 61.4, y = 19.1 }, steps = { { name = "Shadra's Venom", area = 47, x = 33.8, y = 73.0, mobs = { "Shadra" } } }, objective = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill." },
    { id = 2938, name = "Venom to the Undercity", level = 55, minLevel = 40, requires = { 2937 }, faction = "Horde", giver = "Apothecary Lydon", start = { npc = "Apothecary Lydon", area = 267, x = 61.4, y = 19.1 }, finish = { npc = "Master Apothecary Faranell", area = 1497, x = 48.8, y = 69.3 }, objective = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity." },
    { id = 2988, name = "Witherbark Cages", level = 45, minLevel = 40, faction = "Alliance", giver = "Gryphon Master Talonaxe", start = { npc = "Gryphon Master Talonaxe", area = 47, x = 9.8, y = 44.5 }, finish = { npc = "Gryphon Master Talonaxe", area = 47, x = 9.8, y = 44.5 }, steps = { { name = "Check First Cage", area = 47, x = 23.3, y = 58.8 }, { name = "Check Second Cage", area = 47, x = 23.1, y = 58.8 }, { name = "Check Third Cage", area = 47, x = 32.0, y = 57.3 } }, objective = "Check the cages at the two Witherbark villages, then return to Gryphon Master Talonaxe." },
    { id = 2989, name = "The Altar of Zul", level = 48, minLevel = 40, requires = { 2988 }, faction = "Alliance", giver = "Gryphon Master Talonaxe", start = { npc = "Gryphon Master Talonaxe", area = 47, x = 9.8, y = 44.5 }, finish = { npc = "Gryphon Master Talonaxe", area = 47, x = 9.8, y = 44.5 }, steps = { { name = "Search the Altar of Zul", area = 47, x = 48.9, y = 68.4 } }, objective = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe." },
    { id = 2990, name = "Thadius Grimshade", level = 47, minLevel = 40, requires = { 2989 }, faction = "Alliance", giver = "Gryphon Master Talonaxe", start = { npc = "Gryphon Master Talonaxe", area = 47, x = 9.8, y = 44.5 }, finish = { npc = "Thadius Grimshade", area = 4, x = 66.9, y = 19.5 }, objective = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands." },
