    { id = 7701, name = "WANTED: Overseer Maltorius", level = 50, minLevel = 45, giver = "Wanted/Missing/Lost & Found", start = { npc = "Wanted/Missing/Lost & Found", area = 51, x = 37.7, y = 26.5 }, finish = { npc = "Lookout Captain Lolo Longstriker", area = 51, x = 37.7, y = 26.6 }, steps = { { name = "Head of Overseer Maltorius", area = 51, x = 40.8, y = 35.9, mobs = { "Overseer Maltorius" } } }, objective = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.  Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward." },
    { id = 7722, name = "What the Flux?", level = 50, minLevel = 45, giver = "Master Smith Burninate", start = { npc = "Master Smith Burninate", area = 51, x = 38.8, y = 28.5 }, finish = { npc = "Master Smith Burninate", area = 51, x = 38.8, y = 28.5 }, steps = { { name = "Secret Plans: Fiery Flux", area = 51, x = 40.5, y = 35.7 } }, objective = "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge." },
    { id = 7723, name = "Curse These Fat Fingers", level = 49, minLevel = 45, giver = "Hansel Heavyhands", start = { npc = "Hansel Heavyhands", area = 51, x = 38.6, y = 27.8 }, finish = { npc = "Hansel Heavyhands", area = 51, x = 38.6, y = 27.8 }, steps = { { name = "Heavy War Golem", area = 51, x = 39.6, y = 43.8 } }, objective = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.  The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge." },
    { id = 7724, name = "Fiery Menace!", level = 49, minLevel = 45, giver = "Hansel Heavyhands", start = { npc = "Hansel Heavyhands", area = 51, x = 38.6, y = 27.8 }, finish = { npc = "Hansel Heavyhands", area = 51, x = 38.6, y = 27.8 }, steps = { { name = "Greater Lava Spider", area = 51, x = 27.5, y = 71.4 } }, objective = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.  Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders." },
    { id = 7727, name = "Incendosaurs? Whateverosaur is More Like It", level = 49, minLevel = 45, giver = "Hansel Heavyhands", start = { npc = "Hansel Heavyhands", area = 51, x = 38.6, y = 27.8 }, finish = { npc = "Hansel Heavyhands", area = 51, x = 38.6, y = 27.8 }, steps = { { name = "Incendosaur", area = 51, x = 48.0, y = 26.2 } }, objective = "Hansel Heavyhands wants you to kill 20 Incendosaurs.  You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.  Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs." },
    { id = 7728, name = "STOLEN: Smithing Tuyere and Lookout's Spyglass", level = 48, minLevel = 45, giver = "Wanted/Missing/Lost & Found", start = { npc = "Wanted/Missing/Lost & Found", area = 51, x = 37.7, y = 26.5 }, finish = { npc = "Taskmaster Scrange", area = 51, x = 39.0, y = 27.5 }, steps = { { name = "Smithing Tuyere", area = 51, x = 39.9, y = 50.1, mobs = { "Dark Iron Steamsmith" } }, { name = "Lookout's Spyglass", area = 51, x = 46.6, y = 59.5, mobs = { "Dark Iron Lookout" } } }, objective = "Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.  The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts." },
    { id = 7729, name = "JOB OPPORTUNITY: Culling the Competition", level = 48, minLevel = 45, giver = "Wanted/Missing/Lost & Found", start = { npc = "Wanted/Missing/Lost & Found", area = 51, x = 37.7, y = 26.5 }, finish = { npc = "Taskmaster Scrange", area = 51, x = 39.0, y = 27.5 }, steps = { { name = "Dark Iron Taskmaster", area = 51, x = 41.3, y = 37.9 }, { name = "Dark Iron Slaver", area = 51, x = 40.7, y = 52.3 } }, objective = "Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task." },
    { id = 7736, name = "Restoring Fiery Flux Supplies via Kingsblood", level = 60, minLevel = 45, requires = { 7722 }, giver = "Master Smith Burninate", start = { npc = "Master Smith Burninate", area = 51, x = 38.8, y = 28.5 }, finish = { npc = "Master Smith Burninate", area = 51, x = 38.8, y = 28.5 }, steps = { { name = "Incendosaur Scale", area = 51, x = 48.0, y = 26.2, mobs = { "Incendosaur" } }, { name = "Kingsblood", area = 33, x = 41.4, y = 33.3 } } },
