    { id = 5542, name = "Demon Dogs", level = 56, minLevel = 52, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Plaguehound Runt", area = 139, x = 19.7, y = 74.4 }, { name = "Plaguehound", area = 139, x = 70.8, y = 64.6 }, { name = "Frenzied Plaguehound", area = 139, x = 56.2, y = 34.0 } }, objective = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete." },
    { id = 5543, name = "Blood Tinged Skies", level = 56, minLevel = 52, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Plaguebat", area = 139, x = 20.6, y = 73.2 } }, objective = "Slay 30 Plaguebats and return to Tirion Fordring." },
    { id = 5544, name = "Carrion Grubbage", level = 56, minLevel = 52, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Slab of Carrion Worm Meat", area = 139, x = 62.4, y = 56.8, mobs = { "Carrion Grub", "Carrion Devourer" } } }, objective = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat." },
    { id = 5601, name = "Sister Pamela", level = 55, minLevel = 50, giver = "Jessica Redpath", start = { npc = "Jessica Redpath", area = 618, x = 61.3, y = 39.0 }, finish = { npc = "Pamela Redpath", area = 139, x = 36.5, y = 90.8 }, objective = "Find Pamela Redpath in Darrowshire." },
    { id = 5721, name = "The Battle of Darrowshire", level = 60, minLevel = 55, requires = { 5941 }, giver = "Chromie", start = { npc = "Chromie", area = 28, x = 39.5, y = 66.8 }, finish = { npc = "Pamela Redpath", area = 139, x = 36.5, y = 90.8 }, steps = { { name = "Joseph Redpath", area = 139, x = 39.2, y = 91.3 } }, objective = "Place the Relic Bundle at the Darrowshire town square.  Prevent Davil Lightfire's death until the death of Horgus.  Prevent Captain Redpath's death until Redpath the Corrupted appears.  Defeat Redpath the Corrupted.  Speak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home." },
    { id = 5742, name = "Redemption", level = 56, minLevel = 52, requires = { 5542, 5543, 5544 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 } }, objective = "Listen to what Tirion Fordring has to say." },
    { id = 5781, name = "Of Forgotten Memories", level = 57, minLevel = 52, requires = { 5742 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Taelan's Hammer", area = 139, x = 28.3, y = 86.6, mobs = { "Mercutio Filthgorger" } } }, objective = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective." },
    { id = 5845, name = "Of Lost Honor", level = 58, minLevel = 52, requires = { 5781 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Symbol of Lost Honor", area = 139, x = 71.3, y = 34.0 } }, objective = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective." },
    { id = 5846, name = "Of Love and Family", level = 58, minLevel = 52, requires = { 5845 }, giver = "Tirion Fordring", start = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, finish = { npc = "Artist Renfray", area = 28, x = 65.8, y = 75.4 }, objective = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting." },
    { id = 5941, name = "Return to Chromie", level = 60, minLevel = 54, requires = { 5206 }, giver = "Carlin Redpath", start = { npc = "Carlin Redpath", area = 139, x = 81.5, y = 59.8 }, finish = { npc = "Chromie", area = 28, x = 39.5, y = 66.8 }, objective = "Take the Bundle of Relics to Chromie in Andorhal." },
    { id = 5942, name = "Hidden Treasures", level = 60, minLevel = 59, requires = { 5721 }, giver = "Pamela Redpath", start = { npc = "Pamela Redpath", area = 139, x = 36.5, y = 90.8 }, finish = { npc = "Joseph's Chest", area = 139, x = 36.2, y = 90.6 }, objective = "Bring Joseph's Key to Joseph's Chest." },
    { id = 6021, name = "Zaeldarr the Outcast", level = 55, minLevel = 50, giver = "Caretaker Alen", start = { npc = "Caretaker Alen", area = 139, x = 79.6, y = 63.9 }, finish = { npc = "Caretaker Alen", area = 139, x = 79.6, y = 63.9 }, steps = { { name = "Zaeldarr's Head", area = 139, x = 27.5, y = 84.9, mobs = { "Zaeldarr the Outcast" } } }, objective = "Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel." },
    { id = 6022, name = "To Kill With Purpose", level = 58, minLevel = 54, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, objective = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot." },
    { id = 6024, name = "Hameya's Plea", level = 60, minLevel = 54, giver = "Torn Scroll", start = { npc = "Torn Scroll", area = 139, x = 27.3, y = 85.2 }, finish = { npc = "Mound of Dirt", area = 139, x = 28.0, y = 86.2 }, steps = { { name = "Hameya's Key", area = 139, x = 70.7, y = 16.5, mobs = { "Infiltrator Hameya" } } }, objective = "Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft." },
    { id = 6026, name = "That's Asking A Lot", level = 58, minLevel = 54, giver = "Smokey LaRue", start = { npc = "Smokey LaRue", area = 139, x = 80.6, y = 58.0 }, finish = { npc = "Smokey LaRue", area = 139, x = 80.6, y = 58.0 }, objective = "Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.  You will have to find a blacksmith and an engineer for these items." },
    { id = 6041, name = "When Smokey Sings, I Get Violent", level = 58, minLevel = 54, requires = { 6026 }, giver = "Smokey LaRue", start = { npc = "Smokey LaRue", area = 139, x = 80.6, y = 58.0 }, finish = { npc = "Smokey LaRue", area = 139, x = 80.6, y = 58.0 }, steps = { { name = "Scourge Structures Destroyed", area = 139, x = 32.3, y = 32.5 } }, objective = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.  Once you plant the bomb, leave the building and marvel at your handiwork.  By the way, Smokey's Special Compound is rather... unstable." },
    { id = 6042, name = "Un-Life's Little Annoyances", level = 58, minLevel = 54, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "Noxious Plaguebat", area = 139, x = 55.4, y = 58.5 }, { name = "Monstrous Plaguebat", area = 139, x = 55.7, y = 32.5 } }, objective = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished." },
    { id = 6133, name = "The Ranger Lord's Behest", level = 60, minLevel = 54, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "Pathstrider", area = 139, x = 53.3, y = 18.1 }, { name = "Ranger", area = 139, x = 52.2, y = 18.5 }, { name = "Woodsman", area = 139, x = 52.4, y = 18.4 }, { name = "Quel'Thalas Registry", area = 139, x = 52.1, y = 18.3 } }, objective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen." },
    { id = 6135, name = "Duskwing, Oh How I Hate Thee...", level = 60, minLevel = 56, requires = { 6022, 6042, 6133 }, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "Patch of Duskwing's Fur", area = 139, x = 30.8, y = 69.8, mobs = { "Duskwing" } } }, objective = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.  It is said that Duskwing roams the countryside to the north of Marris Stead." },
    { id = 6136, name = "The Corpulent One", level = 60, minLevel = 56, requires = { 6022, 6042, 6133 }, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "Borelgore", area = 139, x = 54.8, y = 31.8 } }, objective = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete." },
    { id = 6144, name = "The Call to Command", level = 60, minLevel = 56, requires = { 6135, 6136 }, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Varimathras", area = 1497, x = 56.3, y = 92.2 }, objective = "Travel to the Undercity and speak with Varimathras." },
    { id = 6145, name = "The Crimson Courier", level = 60, minLevel = 56, requires = { 6144 }, faction = "Horde", giver = "Varimathras", start = { npc = "Varimathras", area = 1497, x = 56.3, y = 92.2 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "The Grand Crusader's Command", area = 139, x = 58.9, y = 38.2, mobs = { "Crimson Courier" } } }, objective = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.  Take the command to Nathanos Blightcaller for further instruction." },
    { id = 6146, name = "Nathanos' Ruse", level = 60, minLevel = 56, requires = { 6145 }, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Crusader Lord Valdelmar", area = 139, x = 85.4, y = 83.2 }, objective = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar." },
    { id = 6147, name = "Return to Nathanos", level = 60, minLevel = 56, requires = { 6146 }, faction = "Horde", giver = "Crusader Lord Valdelmar", start = { npc = "Crusader Lord Valdelmar", area = 139, x = 85.4, y = 83.2 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, objective = "Return to Nathanos Blightcaller with the new information." },
    { id = 6148, name = "The Scarlet Oracle, Demetria", level = 60, minLevel = 56, requires = { 6147 }, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "Demetria", area = 139, x = 72.2, y = 78.9 } }, objective = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed." },
    { id = 6164, name = "Augustus' Receipt Book", level = 55, minLevel = 50, giver = "Augustus the Touched", start = { npc = "Augustus the Touched", area = 139, x = 14.5, y = 33.5 }, finish = { npc = "Augustus the Touched", area = 139, x = 14.5, y = 33.5 }, steps = { { name = "Augustus' Receipt Book", area = 139, x = 17.4, y = 31.1 } }, objective = "Bring Augustus' Receipt Book to Augustus the Touched in Terrordale." },
    { id = 6185, name = "The Eastern Plagues", level = 60, minLevel = 56, requires = { 6184 }, faction = "Alliance", giver = "Flint Shadowmore", start = { npc = "Flint Shadowmore", area = 28, x = 43.6, y = 84.5 }, finish = { npc = "Flint Shadowmore", area = 28, x = 43.6, y = 84.5 }, steps = { { name = "SI:7 Insignia (Rutger)", area = 139, x = 28.8, y = 79.8 }, { name = "SI:7 Insignia (Fredo)", area = 139, x = 27.2, y = 75.0 }, { name = "SI:7 Insignia (Turyen)", area = 139, x = 28.8, y = 74.9 }, { name = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, { name = "The Blightcaller Uncovered", area = 139, x = 27.4, y = 75.1 } }, objective = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp." },
    { id = 6187, name = "Order Must Be Restored", level = 60, minLevel = 56, requires = { 6186 }, faction = "Alliance", giver = "Highlord Bolvar Fordragon", start = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 78.2, y = 18.0 }, finish = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 78.2, y = 18.0 }, steps = { { name = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 } }, objective = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.  Keep your wits about you, <Name>. The Horde will defend the ranger lord with their very lives." },
