    { id = 8930, name = "In Search of Anthion", level = 60, minLevel = 58, requiresAny = { 8927, 8938, 8939, 8940, 8941, 8942, 8943, 8944, 10495 }, faction = "Horde", giver = "Mokvar", start = { npc = "Mokvar", area = 1637, x = 35.0, y = 38.3 }, finish = { npc = "Anthion Harmon", area = 139, x = 30.9, y = 16.8 }, objective = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon." },
