    { id = 9121, name = "The Dread Citadel - Naxxramas (1/3)", level = 60, minLevel = 60, giver = "Archmage Angela Dosantos", start = { npc = "Archmage Angela Dosantos", area = 139, x = 81.5, y = 58.3 }, finish = { npc = "Archmage Angela Dosantos", area = 139, x = 81.5, y = 58.3 }, steps = { { name = "Arcane Crystal", area = 46, x = 78.8, y = 43.4 }, { name = "Righteous Orb", area = 2017, mobs = { "Archivist Galford", "Crimson Battle Mage", "Crimson Conjuror", "Crimson Defender" } } }, objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn." },
