    { id = 5096, name = "Scarlet Diversions", level = 53, minLevel = 50, faction = "Horde", giver = "High Executor Derrington", start = { npc = "High Executor Derrington", area = 85, x = 83.1, y = 68.9 }, finish = { npc = "High Executor Derrington", area = 85, x = 83.1, y = 68.9 }, steps = { { name = "Destroy the command tent and plant the Scourge banner in the camp", area = 28, x = 40.7, y = 52.0 } }, objective = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.  Place the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands." },
    { id = 5097, name = "All Along the Watchtowers", level = 56, minLevel = 50, requires = { 5092 }, faction = "Alliance", giver = "Commander Ashlam Valorfist", start = { npc = "Commander Ashlam Valorfist", area = 28, x = 42.7, y = 84.0 }, finish = { npc = "Commander Ashlam Valorfist", area = 28, x = 42.7, y = 84.0 }, steps = { { name = "Andorhal Tower One", area = 28, x = 40.1, y = 71.6 }, { name = "Andorhal Tower Two", area = 28, x = 42.3, y = 66.2 }, { name = "Andorhal Tower Three", area = 28, x = 44.3, y = 63.3 }, { name = "Andorhal Tower Four", area = 28, x = 46.6, y = 71.1 } }, objective = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.  Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands." },
