    { id = 1124, name = "Wasteland", level = 55, minLevel = 54, requiresAny = { 1123, 6762 }, giver = "Rabine Saturna", start = { npc = "Rabine Saturna", area = 493, x = 51.7, y = 45.1 }, finish = { npc = "Layo Starstrike", area = 1377, x = 81.9, y = 18.9 }, objective = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter." },
    { id = 1185, name = "Under the Chitin Was...", level = 57, minLevel = 55, requires = { 6845 }, giver = "Umber", start = { npc = "Umber", area = 493, x = 44.9, y = 35.6 }, finish = { npc = "Umber", area = 493, x = 44.9, y = 35.6 } },
    { id = 5526, name = "Shards of the Felvine", level = 60, minLevel = 56, requires = { 5527 }, giver = "Rabine Saturna", start = { npc = "Rabine Saturna", area = 493, x = 51.7, y = 45.1 }, finish = { npc = "Rabine Saturna", area = 493, x = 51.7, y = 45.1 }, objective = "Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade." },
    { id = 5527, name = "A Reliquary of Purity", level = 60, minLevel = 56, giver = "Rabine Saturna", start = { npc = "Rabine Saturna", area = 493, x = 51.7, y = 45.1 }, finish = { npc = "Rabine Saturna", area = 493, x = 51.7, y = 45.1 }, steps = { { name = "Reliquary of Purity", area = 1377, x = 63.2, y = 55.4 } }, objective = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade." },
    { id = 6845, name = "Uncovering Past Secrets", level = 57, minLevel = 54, requires = { 6844 }, giver = "Umber", start = { npc = "Umber", area = 493, x = 44.9, y = 35.6 }, finish = { npc = "Rabine Saturna", area = 493, x = 51.7, y = 45.1 }, objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade." },
    { id = 8735, name = "The Nightmare's Corruption", level = 60, minLevel = 60, requires = { 8734 }, giver = "Keeper Remulos", start = { npc = "Keeper Remulos", area = 493, x = 36.2, y = 41.8 }, finish = { npc = "Keeper Remulos", area = 493, x = 36.2, y = 41.8 }, steps = { { name = "Fragment of the Nightmare's Corruption", area = 331, x = 92.4, y = 38.7, mobs = { "Emeraldon Boughguard", "Emeraldon Oracle", "Emeraldon Tree Warder" } }, { name = "Fragment of the Nightmare's Corruption", area = 10, x = 48.6, y = 40.0, mobs = { "Twilight Corrupter" } }, { name = "Fragment of the Nightmare's Corruption", area = 357, x = 51.3, y = 11.3, mobs = { "Jademir Boughguard", "Jademir Oracle", "Jademir Tree Warder" } }, { name = "Fragment of the Nightmare's Corruption", area = 47, x = 63.4, y = 27.7, mobs = { "Verdantine Boughguard", "Verdantine Oracle", "Verdantine Tree Warder" } } }, objective = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task." },
    { id = 8736, name = "The Nightmare Manifests", level = 60, minLevel = 60, requires = { 8735 }, giver = "Keeper Remulos", start = { npc = "Keeper Remulos", area = 493, x = 36.2, y = 41.8 }, finish = { npc = "Keeper Remulos", area = 493, x = 36.2, y = 41.8 }, steps = { { name = "The Redemption of Eranikus", area = 493, x = 51.8, y = 36.4 } }, objective = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande." },
    { id = 8741, name = "The Champion Returns", level = 60, minLevel = 60, requires = { 8736 }, giver = "Keeper Remulos", start = { npc = "Keeper Remulos", area = 493, x = 36.2, y = 41.8 }, finish = { npc = "Anachronos", area = 440, x = 64.2, y = 51.4 }, objective = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris." },
})

