    { id = 1126, name = "Hive in the Tower", level = 57, minLevel = 54, requires = { 1125 }, giver = "Layo Starstrike", start = { npc = "Layo Starstrike", area = 1377, x = 81.9, y = 18.9 }, finish = { npc = "Layo Starstrike", area = 1377, x = 81.9, y = 18.9 }, steps = { { name = "Encrusted Silithid Object", area = 1377, x = 60.2, y = 52.5, mobs = { "Hive'Ashi Ambusher" } } }, objective = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity. Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus." },
    { id = 6844, name = "Umber, Archivist", level = 57, minLevel = 54, requires = { 1126 }, giver = "Layo Starstrike", start = { npc = "Layo Starstrike", area = 1377, x = 81.9, y = 18.9 }, finish = { npc = "Umber", area = 493, x = 44.9, y = 35.6 }, objective = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade." },
    { id = 8277, name = "Deadly Desert Venom", level = 55, minLevel = 54, giver = "Beetix Ficklespragg", start = { npc = "Beetix Ficklespragg", area = 1377, x = 51.6, y = 38.6 }, finish = { npc = "Beetix Ficklespragg", area = 1377, x = 51.6, y = 38.6 }, steps = { { name = "Stonelash Scorpid Stinger", area = 1377, x = 61.6, y = 26.8, mobs = { "Stonelash Scorpid" } }, { name = "Sand Skitterer Fang", area = 1377, x = 57.3, y = 21.1, mobs = { "Sand Skitterer" } } }, objective = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task." },
