    { id = 8280, name = "Securing the Supply Lines", level = 55, minLevel = 54, requiresAny = { 8275, 8276 }, giver = "Windcaller Proudhorn", start = { npc = "Windcaller Proudhorn", area = 1377, x = 51.2, y = 38.3 }, finish = { npc = "Windcaller Proudhorn", area = 1377, x = 51.2, y = 38.3 }, steps = { { name = "Dredge Striker", area = 1377, x = 57.0, y = 20.3 } }, objective = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers." },
