    { id = 8282, name = "Noggle's Lost Satchel", level = 58, minLevel = 54, requires = { 8278 }, giver = "Noggle Ficklespragg", start = { npc = "Noggle Ficklespragg", area = 1377, x = 51.6, y = 38.5 }, finish = { npc = "Noggle Ficklespragg", area = 1377, x = 51.6, y = 38.5 }, steps = { { name = "Noggle's Satchel", area = 1377, x = 44.6, y = 91.4 } }, objective = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold." },
    { id = 8283, name = "Wanted - Deathclasp, Terror of the Sands", level = 59, minLevel = 54, giver = "Wanted Poster: Deathclasp", start = { npc = "Wanted Poster: Deathclasp", area = 1377, x = 51.4, y = 38.3 }, finish = { npc = "Vish Kozus", area = 1377, x = 50.8, y = 33.7 }, steps = { { name = "Deathclasp's Pincer", area = 1377, x = 45.1, y = 92.3, mobs = { "Deathclasp" } } }, objective = "Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard." },
    { id = 8284, name = "The Twilight Mystery", level = 58, minLevel = 54, giver = "Geologist Larksbane", start = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, finish = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, steps = { { name = "Twilight Tablet Fragment", area = 1377, x = 22.9, y = 12.8 } }, objective = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments." },
    { id = 8285, name = "The Deserter", level = 59, minLevel = 54, requires = { 8284 }, giver = "Geologist Larksbane", start = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, finish = { npc = "Hermit Ortell", area = 1377, x = 67.2, y = 69.8 }, objective = "Take the restored tablet to Hermit Ortell in Silithus." },
    { id = 8286, name = "What Tomorrow Brings", level = 60, minLevel = 60, giver = "Baristolth of the Shifting Sands", start = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, finish = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, steps = { { name = "Anachronos", area = 440, x = 64.2, y = 51.4 }, { name = "Discover the Brood of Nozdormu.", area = 440, x = 63.8, y = 50.9 } }, objective = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu." },
    { id = 8287, name = "A Terrible Purpose", level = 60, minLevel = 54, requires = { 8279 }, giver = "Hermit Ortell", start = { npc = "Hermit Ortell", area = 1377, x = 67.2, y = 69.8 }, finish = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, objective = "Take the Decoded Tablet Parchment to Commander Mar'alith." },
    { id = 8301, name = "The Path of the Righteous", level = 60, minLevel = 60, requires = { 8288 }, giver = "Baristolth of the Shifting Sands", start = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, finish = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, steps = { { name = "Silithid Carapace Fragment", area = 1377, x = 25.4, y = 63.2, mobs = { "Hive'Zora Wasp", "Hive'Ashi Swarmer", "Hive'Regal Slavemaker", "Hive'Regal Spitfire" } } }, objective = "Collect 200 Silithid Carapace Fragments and return to Baristolth." },
    { id = 8302, name = "The Hand of the Righteous", level = 60, minLevel = 60, requires = { 8301 }, giver = "Baristolth of the Shifting Sands", start = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, finish = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, steps = { { name = "Silithid Carapace Fragment", area = 1377, x = 25.4, y = 63.2, mobs = { "Hive'Zora Wasp", "Hive'Ashi Swarmer", "Hive'Regal Slavemaker", "Hive'Regal Spitfire" } } }, objective = "Collect 200 Silithid Carapace Fragments and return to Baristolth." },
    { id = 8303, name = "Anachronos", level = 60, minLevel = 60, requires = { 8301 }, giver = "Baristolth of the Shifting Sands", start = { npc = "Baristolth of the Shifting Sands", area = 1377, x = 49.5, y = 36.5 }, finish = { npc = "Anachronos", area = 440, x = 64.2, y = 51.4 }, objective = "Seek out Anachronos at the Caverns of Time in Tanaris." },
    { id = 8304, name = "Dearest Natalia", level = 60, minLevel = 58, giver = "Commander Mar'alith", start = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, finish = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, steps = { { name = "Frankal Stonebridge", area = 1377, x = 40.8, y = 88.9 }, { name = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 } }, objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.  Once you have gathered the requested information, return to Commander Mar'alith." },
    { id = 8305, name = "Long Forgotten Memories", level = 60, minLevel = 60, requires = { 8303 }, giver = "Anachronos", start = { npc = "Anachronos", area = 440, x = 64.2, y = 51.4 }, finish = { npc = "Crystalline Tear", area = 1377, x = 28.7, y = 89.1 }, objective = "Locate the Crystalline Tear in Silithus and gaze into its depths." },
    { id = 8306, name = "Into The Maw of Madness", level = 60, minLevel = 58, requires = { 8304 }, giver = "Commander Mar'alith", start = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, finish = { npc = "Commander Mar'alith", area = 1377, x = 49.2, y = 34.2 }, steps = { { name = "The Fate of Mistress Natalia Mar'alith", area = 10073, x = 44.4, y = 86.1 } }, objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.  Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.  And <Name>, remember the Commander's words: \"Do what you must...\"" },
    { id = 8308, name = "Brann Bronzebeard's Lost Letter", level = 60, minLevel = 58, giver = "Brann Bronzebeard's Lost Letter", start = { npc = "Brann Bronzebeard's Lost Letter", area = 1377, x = 25.4, y = 63.2 }, finish = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, objective = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus." },
    { id = 8309, name = "Glyph Chasing", level = 60, minLevel = 58, requires = { 8304 }, giver = "Rutgar Glyphshaper", start = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, finish = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, steps = { { name = "Hive'Ashi Rubbing", area = 1377, x = 50.9, y = 26.8 }, { name = "Hive'Zora Rubbing", area = 1377, x = 37.3, y = 62.5 }, { name = "Hive'Regal Rubbing", area = 10073, x = 44.4, y = 86.1 } }, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.  Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task." },
    { id = 8310, name = "Breaking the Code", level = 60, minLevel = 58, requires = { 8304 }, giver = "Frankal Stonebridge", start = { npc = "Frankal Stonebridge", area = 1377, x = 40.8, y = 88.9 }, finish = { npc = "Frankal Stonebridge", area = 1377, x = 40.8, y = 88.9 }, steps = { { name = "Hive'Ashi Silithid Brain", area = 1377, x = 44.4, y = 21.0, mobs = { "Hive'Ashi Swarmer", "Hive'Ashi Defender", "Hive'Ashi Stinger", "Hive'Ashi Sandstalker" } }, { name = "Hive'Zora Silithid Brain", area = 1377, x = 25.4, y = 63.2, mobs = { "Hive'Zora Wasp", "Hive'Zora Hive Sister", "Hive'Zora Reaver", "Hive'Zora Waywatcher" } }, { name = "Hive'Regal Silithid Brain", area = 1377, x = 58.1, y = 80.2, mobs = { "Hive'Regal Slavemaker", "Hive'Regal Spitfire", "Hive'Regal Hive Lord", "Hive'Regal Ambusher" } } }, objective = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task." },
    { id = 8314, name = "Unraveling the Mystery", level = 60, minLevel = 58, requires = { 8309, 8310 }, giver = "Rutgar Glyphshaper", start = { npc = "Rutgar Glyphshaper", area = 1377, x = 41.3, y = 88.5 }, finish = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus." },
    { id = 8315, name = "The Calling", level = 60, minLevel = 58, requires = { 8314 }, giver = "Geologist Larksbane", start = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, finish = { npc = "Geologist Larksbane", area = 1377, x = 49.7, y = 37.5 }, steps = { { name = "Crystal Unlocking Mechanism", area = 1377, x = 48.8, y = 58.1, mobs = { "Emissary Roman'khan" } } }, objective = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.  You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.  Assemble an army for this task, <Name>!" },
