    { id = 10555, name = "Malaise", level = 66, minLevel = 65, faction = "Alliance", giver = "Daranelle", start = { npc = "Daranelle", area = 3522, x = 37.1, y = 65.6 }, finish = { npc = "Lashh'an Tome", area = 3522, x = 34.8, y = 78.0 }, steps = { { name = "Plucked Lashh'an Feather", area = 3522, x = 35.2, y = 76.6, mobs = { "Lashh'an Windwalker", "Lashh'an Wing Guard", "Lashh'an Talonite", "Lashh'an Matriarch" } } }, objective = "Collect 18 Plucked Lashh'an Feathers, then read the Lashh'an Tome in the treetops of Veil Lashh." },
    { id = 10556, name = "Scratches", level = 66, minLevel = 65, requires = { 10555 }, faction = "Alliance", giver = "Lashh'an Tome", start = { npc = "Lashh'an Tome", area = 3522, x = 34.8, y = 78.0 }, finish = { npc = "Daranelle", area = 3522, x = 37.1, y = 65.6 }, objective = "Use the Fistful of Feathers on the Lashh'an Spell Circle, then return to Daranelle at Sylvanaar before the kaliri spirit fades." },
    { id = 10557, name = "Test Flight: The Zephyrium Capacitorium", level = 64, minLevel = 62, faction = "Alliance", giver = "Tally Zapnabber", start = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, finish = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, steps = { { name = "Test Tally's Experiment", area = 3522, x = 60.2, y = 68.8 } }, objective = "Speak with Rally Zapnabber and use the Zephyrium Capacitorium. Return to Tally Zapnabber at Toshley's Station." },
    { id = 10565, name = "The Stones of Vekh'nir", level = 66, minLevel = 64, faction = "Horde", giver = "Dertrok", start = { npc = "Dertrok", area = 3522, x = 75.1, y = 62.1 }, finish = { npc = "Dertrok", area = 3522, x = 75.1, y = 62.1 }, objective = "Collect and use a Vekh'nir Crystal at the Vekh'nir Spell Circle, then return the Charged Vekh'nir Crystal to Dertrok at the Mok'Nathal Village." },
    { id = 10566, name = "Trial and Error", level = 66, minLevel = 64, requires = { 10565 }, faction = "Horde", giver = "Dertrok", start = { npc = "Dertrok", area = 3522, x = 75.1, y = 62.1 }, finish = { npc = "Dertrok", area = 3522, x = 75.1, y = 62.1 }, steps = { { name = "Dullgrom Dredger", area = 3522, x = 70.7, y = 73.9 }, { name = "Dullgrom Dredger", area = 3522, x = 70.7, y = 73.9 }, { name = "Dullgrom Dredger", area = 3522, x = 70.7, y = 73.9 }, { name = "Dullgrom Dredger", area = 3522, x = 70.7, y = 73.9 } }, objective = "Try out each of Dertrok's wands on an Arakkoa Ogre Slave, then return to Dertrok. Each wand will require an Infused Vekh'nir Crystal to use." },
    { id = 10567, name = "Creating the Pendant", level = 66, minLevel = 66, giver = "Timeon", start = { npc = "Timeon", area = 3522, x = 62.2, y = 39.1 }, finish = { npc = "Timeon", area = 3522, x = 62.2, y = 39.1 }, steps = { { name = "Harbinger's Pendant", area = 3522, x = 64.5, y = 33.1, mobs = { "Harbinger of the Raven" } } }, objective = "Find 6 Ruuan'ok Claws and use them at the Ruaan'ok Oracle Circle to summon a Harbinger of the Raven. Kill it and return its Harbinger's Pendant to Timeon at Ruuan Weald." },
    { id = 10580, name = "Where Did Those Darn Gnomes Go?", level = 67, minLevel = 65, requires = { 10518 }, faction = "Alliance", giver = "Commander Skyshadow", start = { npc = "Commander Skyshadow", area = 3522, x = 36.2, y = 66.2 }, finish = { npc = "R-3D0", area = 3522, x = 55.1, y = 72.8 }, objective = "Commander Skyshadow has asked you to look in the southern area of the Jagged Ridge of the Blade's Edge Mountains for a clue as to the whereabouts of Toshley and the other gnomes." },
    { id = 10581, name = "Follow the Breadcrumbs", level = 67, minLevel = 65, requires = { 10580 }, faction = "Alliance", giver = "R-3D0", start = { npc = "R-3D0", area = 3522, x = 55.1, y = 72.8 }, finish = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, objective = "In a round-about way, R-3D0 has informed you that if you follow the trail of spare parts up the ramp here to the Razor Ridge, you will find the gnomes at a place named Toshley's Station.  If you find him, speak with Toshley." },
    { id = 10584, name = "Picking Up Some Power Converters", level = 67, minLevel = 65, faction = "Alliance", giver = "Toshley", start = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, finish = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, steps = { { name = "Electromental", area = 3522, x = 57.8, y = 57.1 } }, objective = "Toshley has asked you to take the Protovoltaic Magneto Collector and gather up 5 Electromentals. Return to him at Toshley's Station in the Blade's Edge Mountains after you have done so." },
    { id = 10594, name = "Gauging the Resonant Frequency", level = 67, minLevel = 65, requires = { 10608 }, faction = "Alliance", giver = "Nickwinkle the Metro-Gnome", start = { npc = "Nickwinkle the Metro-Gnome", area = 3522, x = 60.2, y = 68.9 }, finish = { npc = "Nickwinkle the Metro-Gnome", area = 3522, x = 60.2, y = 68.9 }, steps = { { name = "Singing crystal resonant frequency gauged", area = 3522, x = 59.8, y = 73.8 } }, objective = "Nickwinkle the Metro-Gnome wants you to place the Oscillating Frequency Scanners in such a way that when you stand amongst them, you are hit by five overlapping Oscillation fields.  Return to him at Toshley's Station in the Blade's Edge Mountains after you have done so." },
    { id = 10607, name = "Whispers of the Raven God", level = 68, minLevel = 66, requires = { 10567 }, giver = "Timeon", start = { npc = "Timeon", area = 3522, x = 62.2, y = 39.1 }, finish = { npc = "Timeon", area = 3522, x = 62.2, y = 39.1 }, steps = { { name = "The First Prophecy", area = 3522, x = 39.0, y = 17.3 }, { name = "The Second Prophecy", area = 3522, x = 42.5, y = 21.6 }, { name = "The Third Prophecy", area = 3522, x = 40.7, y = 18.6 }, { name = "The Fourth Prophecy", area = 3522, x = 40.2, y = 23.0 } }, objective = "Kill Grishna arakkoa to gain Understanding Ravenspeech for 2 minutes. While under the effects of the spell, you can find and receive the prophecy from the four shrines. Return when you have visited all four." },
    { id = 10608, name = "Crystal Clear", level = 67, minLevel = 65, faction = "Alliance", giver = "Nickwinkle the Metro-Gnome", start = { npc = "Nickwinkle the Metro-Gnome", area = 3522, x = 60.2, y = 68.9 }, finish = { npc = "Nickwinkle the Metro-Gnome", area = 3522, x = 60.2, y = 68.9 }, steps = { { name = "Crystal Flayer", area = 3522, x = 62.6, y = 75.8 } }, objective = "Nickwinkle the Metro-Gnome wants you to slay 10 Crystal Flayers and then return to him at Toshley's Station in the Blade's Edge Mountains." },
    { id = 10609, name = "What Came First, the Drake or the Egg?", level = 67, minLevel = 65, faction = "Alliance", giver = "Fizit \"Doc\" Clocktock", start = { npc = "Fizit \"Doc\" Clocktock", area = 3522, x = 61.0, y = 68.1 }, finish = { npc = "Fizit \"Doc\" Clocktock", area = 3522, x = 61.0, y = 68.1 }, steps = { { name = "Proto-Nether Drake Essence", area = 3522, x = 63.5, y = 76.6, mobs = { "Nether Whelp" } }, { name = "Adolescent Nether Drake Essence", area = 3522, x = 63.5, y = 76.6, mobs = { "Nether Whelp" } }, { name = "Mature Nether Drake Essence", area = 3522, x = 63.5, y = 76.6, mobs = { "Nether Whelp" } } }, objective = "Collect 3 Proto-Nether Drake Essences, 3 Adolescent Drake Essences and 3 Mature Drake Essences. Return with them to Fizit \"Doc\" Clocktock at Toshley's Station in the Blade's Edge Mountains." },
    { id = 10614, name = "Whispers on the Wind", level = 66, minLevel = 65, requires = { 10718 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, finish = { npc = "Leoroxx", area = 3522, x = 75.3, y = 60.9 }, objective = "Search out Leoroxx at the Mok'Nathal Village in the Blade's Edge Mountains." },
    { id = 10615, name = "Ruuan Weald", level = 64, minLevel = 64, requires = { 10566 }, faction = "Horde", giver = "Dertrok", start = { npc = "Dertrok", area = 3522, x = 75.1, y = 62.1 }, finish = { npc = "Timeon", area = 3522, x = 62.2, y = 39.1 }, objective = "Speak with Timeon at Evergrove, which is in the Ruuan Weald in the Blade's Edge Mountains." },
    { id = 10617, name = "Silkwing Cocoons", level = 66, minLevel = 64, faction = "Horde", giver = "Taerek", start = { npc = "Taerek", area = 3522, x = 75.9, y = 61.4 }, finish = { npc = "Taerek", area = 3522, x = 75.9, y = 61.4 }, steps = { { name = "Silkwing Cocoon", area = 3522, x = 74.4, y = 71.1, mobs = { "Silkwing Larva" } } }, objective = "Taerek at Mok'Nathal Village wants you to collect 8 Silkwing Cocoons from Silkwing Larva.  Kill the Larva quickly or they will turn into Silkwings, ruining their cocoons." },
    { id = 10618, name = "The Softest Wings", level = 65, minLevel = 64, faction = "Horde", giver = "Silmara", start = { npc = "Silmara", area = 3522, x = 75.8, y = 61.5 }, finish = { npc = "Silmara", area = 3522, x = 75.8, y = 61.5 }, steps = { { name = "Iridescent Wing", area = 3522, x = 73.6, y = 68.9, mobs = { "Mature Silkwing" } } }, objective = "Silmara at Mok'Nathal Village wants you to collect 12 Iridescent Wings." },
    { id = 10620, name = "Ridgespine Menace", level = 67, minLevel = 65, requires = { 10584 }, faction = "Alliance", giver = "Dizzy Dina", start = { npc = "Dizzy Dina", area = 3522, x = 60.4, y = 68.8 }, finish = { npc = "Dizzy Dina", area = 3522, x = 60.4, y = 68.8 }, steps = { { name = "Ridgespine Stalker", area = 3522, x = 66.5, y = 54.7 } }, objective = "Dizzy Dina wants you to kill 10 Ridgespine Stalkers. After you have done so, return to her at Toshley's Station in the Blade's Edge Mountains." },
    { id = 10632, name = "Cutting Your Teeth", level = 67, minLevel = 65, requires = { 10584 }, faction = "Alliance", giver = "Razak Ironsides", start = { npc = "Razak Ironsides", area = 3522, x = 60.2, y = 68.2 }, finish = { npc = "Razak Ironsides", area = 3522, x = 60.2, y = 68.2 }, steps = { { name = "Extra Sharp Daggermaw Tooth", area = 3522, x = 65.0, y = 54.4, mobs = { "Daggermaw Lashtail" } } }, objective = "Razak Ironsides has asked you to gather up 5 Extra Sharp Daggermaw Teeth. Return them to him at Toshley's Station in the Blade's Edge Mountains." },
    { id = 10657, name = "Ride the Lightning", level = 67, minLevel = 65, requires = { 10584 }, faction = "Alliance", giver = "Toshley", start = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, finish = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, steps = { { name = "Scalewing Serpent", area = 3522, x = 68.1, y = 68.6 }, { name = "Scalewing Lightning Gland", area = 3522, x = 68.1, y = 68.6, mobs = { "Scalewing Serpent" } } }, objective = "Toshley wants you to use the Repolarized Magneto Sphere to absorb 25 lightning strikes from the Scalewing Serpents. As well, collect 5 Scalewing Lightning Glands. Then, deliver them back to him at Toshley's Station in the Blade's Edge Mountains." },
    { id = 10671, name = "More than a Pound of Flesh", level = 67, minLevel = 65, requires = { 10620 }, faction = "Alliance", giver = "Dizzy Dina", start = { npc = "Dizzy Dina", area = 3522, x = 60.4, y = 68.8 }, finish = { npc = "Dizzy Dina", area = 3522, x = 60.4, y = 68.8 }, steps = { { name = "Ether-Energized Flesh", area = 3522, x = 66.8, y = 43.8, mobs = { "Fiendling Flesh Beast" } } }, objective = "Dizzy Dina has asked you to acquire 5 Ether-Energized Flesh and return them to her at Toshley's Station in the Blade's Edge Mountains." },
