    { id = 10675, name = "Show Them Gnome Mercy!", level = 68, minLevel = 65, requires = { 10674 }, faction = "Alliance", giver = "Toshley", start = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, finish = { npc = "Toshley", area = 3522, x = 60.5, y = 69.0 }, steps = { { name = "Collection of Souls", area = 3522, x = 66.4, y = 44.1 } }, objective = "Toshley wants you to retrieve the Collection of Souls and return it to him at Toshley's Station in the Blade's Edge Mountains." },
    { id = 10682, name = "A Time for Negotiation...", level = 67, minLevel = 65, giver = "Tree Warden Chawn", start = { npc = "Tree Warden Chawn", area = 3522, x = 62.0, y = 39.5 }, finish = { npc = "Tree Warden Chawn", area = 3522, x = 62.0, y = 39.5 }, steps = { { name = "Overseer Nuaar", area = 3522, x = 60.4, y = 34.3 } }, objective = "Tree Warden Chawn has asked you to negotiate with Overseer Nuaar. Return to the tree warden at Evergrove in the Blade's Edge Mountains afterward." },
    { id = 10690, name = "The Den Mother", level = 66, minLevel = 65, faction = "Alliance", giver = "Wanted Poster", start = { npc = "Wanted Poster", area = 3522, x = 36.6, y = 67.3 }, finish = { npc = "Commander Skyshadow", area = 3522, x = 36.2, y = 66.2 }, steps = { { name = "Rema", area = 3522, x = 51.6, y = 75.0 } }, objective = "Kill Rema and then inform Commander Skyshadow at Sylvanaar in the Blade's Edge Mountains." },
