    { id = 10710, name = "Test Flight: The Singing Ridge", level = 64, minLevel = 62, requiresAny = { 10557, 10584 }, faction = "Alliance", giver = "Tally Zapnabber", start = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, finish = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, steps = { { name = "Test Tally's Experiment", area = 3522, x = 60.2, y = 68.8 } }, objective = "Sign Tally's Waiver, then speak with Rally Zapnabber to use the Zephyrium Capacitorium. Return to Tally Zapnabber at Toshley's Station." },
    { id = 10711, name = "Test Flight: Razaan's Landing", level = 64, minLevel = 64, requires = { 10710, 10657 }, faction = "Alliance", giver = "Tally Zapnabber", start = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, finish = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, steps = { { name = "Test Tally's Experiment", area = 3522, x = 60.2, y = 68.8 } }, objective = "Speak with Rally Zapnabber to use the Zephyrium Capacitorium. Return to Tally Zapnabber at Toshley's Station." },
    { id = 10712, name = "Test Flight: Ruuan Weald", level = 64, minLevel = 62, requires = { 10711, 10675 }, faction = "Alliance", giver = "Tally Zapnabber", start = { npc = "Tally Zapnabber", area = 3522, x = 60.3, y = 68.4 }, finish = { npc = "O'Mally Zapnabber", area = 3522, x = 62.7, y = 40.4 }, steps = { { name = "Test Tally's Experiment", area = 3522, x = 60.2, y = 68.8 } }, objective = "Speak with Rally Zapnabber to use the Zephyrium Capacitorium. While flying to Ruuan Weald, spin the Nether-weather Vane. Deliver the Spinning Nether-weather Vane to O'Mally Zapnabber in Ruuan Weald." },
    { id = 10713, name = "...and a Time for Action", level = 67, minLevel = 65, requires = { 10682 }, giver = "Tree Warden Chawn", start = { npc = "Tree Warden Chawn", area = 3522, x = 62.0, y = 39.5 }, finish = { npc = "Tree Warden Chawn", area = 3522, x = 62.0, y = 39.5 }, steps = { { name = "Wyrmcult Hewer", area = 3522, x = 60.9, y = 39.1 } }, objective = "Venture out into the Ruuan Weald and slay 10 Wyrmcult Hewers, then return to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains." },
    { id = 10714, name = "On Spirit's Wings", level = 67, minLevel = 65, requires = { 10709 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, finish = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, steps = { { name = "Bloodmaul Taskmaster", area = 3522, x = 56.5, y = 33.4 } }, objective = "Find a Bloodmaul Taskmaster and a Bloodmaul Soothsayer engaged in conversation, then use Rexxar's Whistle to summon Spirit to spy on them. When this is complete, return to Rexxar at Thunderlord Village in the Blade's Edge Mountains." },
    { id = 10715, name = "Into the Churning Gulch", level = 67, minLevel = 65, requires = { 10783 }, faction = "Horde", giver = "Baron Sablemane", start = { npc = "Baron Sablemane", area = 3522, x = 53.3, y = 41.2 }, finish = { npc = "Baron Sablemane", area = 3522, x = 53.3, y = 41.2 }, steps = { { name = "Crust Burster Venom Gland", area = 3522, x = 48.0, y = 43.2, mobs = { "Young Crust Burster", "Greater Crust Burster" } } }, objective = "Baron Sablemane has told you that in order to make the poison that Rexxar needs, you must acquire 7 Crust Burster Venom Glands. Return to him at the Circle of Blood in the Blade's Edge Mountains once you have done so." },
    { id = 10716, name = "BETA Test Flight: Raven's Wood <needs reward>", level = 64, minLevel = 64, objective = "Speak with Rally Zapnabber to use the Zephyrium Capacitorium. Return to Tally Zapnabber at Toshley's Station." },
    { id = 10717, name = "Poaching from Poachers", level = 67, minLevel = 65, requires = { 10682 }, giver = "Samia Inkling", start = { npc = "Samia Inkling", area = 3522, x = 61.9, y = 39.5 }, finish = { npc = "Samia Inkling", area = 3522, x = 61.9, y = 39.5 }, steps = { { name = "Wyrmcult Net", area = 3522, x = 61.1, y = 38.5, mobs = { "Wyrmcult Poacher" } } }, objective = "Samia Inkling has asked you to acquire 5 Wyrmcult Nets and return them to her at Evergrove in the Blade's Edge Mountains." },
    { id = 10718, name = "The Spirits Have Voices", level = 67, minLevel = 65, requires = { 10526 }, faction = "Horde", giver = "Garm Wolfbrother", start = { npc = "Garm Wolfbrother", area = 3522, x = 52.8, y = 59.0 }, finish = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, objective = "Garm Wolfbrother has told you where the Mok'Nathal, Rexxar's people, live. Speak of this to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains." },
    { id = 10719, name = "Did You Get The Note?", level = 67, minLevel = 65, requires = { 10682 }, giver = "Meeting Note", start = { npc = "Meeting Note", area = 3522, x = 61.0, y = 38.7 }, finish = { npc = "Tree Warden Chawn", area = 3522, x = 62.0, y = 39.5 }, objective = "Deliver the Meeting Note to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains." },
    { id = 10720, name = "The Smallest Creatures", level = 67, minLevel = 65, requires = { 10749 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, finish = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, steps = { { name = "Green Spot Grog Keg", area = 3522, x = 55.3, y = 26.0 }, { name = "Ripe Moonshine Keg", area = 3522, x = 55.4, y = 28.2 }, { name = "Fermented Seed Beer Keg", area = 3522, x = 56.0, y = 23.1 } }, objective = "Use the Kodohide Drum at the Marmot Den. While controlling the Marmot, poison the three kegs in the Bloodmaul Camp. When that is completed, return to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains." },
    { id = 10721, name = "A Boaring Time for Grulloc", level = 67, minLevel = 65, requires = { 10720 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, finish = { npc = "Baron Sablemane", area = 3522, x = 53.3, y = 41.2 }, steps = { { name = "Grulloc's Sack", area = 3522, x = 60.9, y = 47.8 } }, objective = "Obtain Grulloc's Sack and deliver it to Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains." },
    { id = 10722, name = "Meeting at the Blackwing Coven", level = 68, minLevel = 65, requires = { 10893 }, giver = "Watcher Moonshade", start = { npc = "Watcher Moonshade", area = 3522, x = 50.0, y = 36.0 }, finish = { npc = "Tree Warden Chawn", area = 3522, x = 62.0, y = 39.5 }, steps = { { name = "Kolphis Darkscale", area = 3522, x = 32.7, y = 37.5 } }, objective = "Gather up enough Costume Scraps from the various wyrmcultists to create an Overseer Disguise. Use the disguise to attend the meeting with Kolphis Darkscale, and report your findings back to Tree Warden Chawn at Evergrove in the Blade's Edge Mountains." },
    { id = 10723, name = "Gorgrom the Dragon-Eater", level = 68, minLevel = 65, requires = { 10785 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, finish = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, steps = { { name = "Gorgrom the Dragon-Eater", area = 3522, x = 30.7, y = 22.1 } }, objective = "Go to Boulder'mok and collect 3 Grisly Totems from the Boulder'mok ogres. Use Sablemane's Trap at Gorgrom's Altar to set the trap and summon and kill Gorgrom the Dragon-Eater.  When Gorgrom is dead, place the 3 Grisly Totems near his corpse, then return to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains." },
    { id = 10724, name = "Prisoner of the Bladespire", level = 67, minLevel = 65, requires = { 10723 }, faction = "Horde", giver = "Rexxar", start = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, finish = { npc = "Rexxar", area = 3522, x = 51.8, y = 58.4 }, steps = { { name = "Leokk", area = 3522, x = 65.7, y = 20.3 } }, objective = "Kill Bladespire ogres to get the Wyvern Cage Key. Once you have it, go to the Wyvern Cage and use Spirit's Whistle to summon Spirit, who will unlock the cage. After Leokk is free, return to Rexxar at Thunderlord Village in the Blade's Edge Mountains." },
