    { id = 10191, name = "Mark V is Alive!", level = 68, minLevel = 67, giver = "Maxx A. Million Mk. V", start = { npc = "Maxx A. Million Mk. V", area = 3523, x = 31.6, y = 56.6 }, finish = { npc = "Bot-Specialist Alley", area = 3523, x = 31.5, y = 56.6 }, steps = { { name = "Escort the Maxx A. Million Mk. V safely through the Ruins of Enkaat", area = 3523, x = 31.5, y = 56.5 } }, objective = "Escort the Maxx A. Million Mk. V through the Ruins of Enkaat and back out to safety. Then speak with Bot-Specialist Alley just outside the Ruins of Enkaat in the Netherstorm." },
