    { id = 10686, name = "The Warden's Cage (2/2)", level = 70, minLevel = 68, requires = { 10685 }, giver = "Arcanist Thelis", start = { npc = "Arcanist Thelis", area = 3520, x = 56.3, y = 59.6 }, finish = { npc = "Sanoru", area = 3520, x = 57.3, y = 49.6 }, objective = "Arcanist Thelis wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.  Completing quests for the Scryers will cause your Aldor reputation to decrease." },
