    { id = 10691, name = "Return to the Scryers", level = 70, minLevel = 69, requires = { 10649 }, giver = "Altruis the Sufferer", start = { npc = "Altruis the Sufferer", area = 3518, x = 27.3, y = 43.1 }, finish = { npc = "Larissa Sunstrike", area = 3520, x = 55.7, y = 58.2 }, objective = "Speak with Larissa Sunstrike at the Sanctum of the Stars in Shadowmoon Valley.  Completing quests for the Scryers will cause your Aldor reputation level to decrease." },
    { id = 10692, name = "Varedis Must Be Stopped (2/2)", level = 70, minLevel = 68, requires = { 10691 }, giver = "Larissa Sunstrike", start = { npc = "Larissa Sunstrike", area = 3520, x = 55.7, y = 58.2 }, finish = { npc = "Larissa Sunstrike", area = 3520, x = 55.7, y = 58.2 }, steps = { { name = "Varedis", area = 3520, x = 72.2, y = 53.7 }, { name = "Netharel", area = 3520, x = 69.0, y = 52.4 }, { name = "Theras", area = 3520, x = 72.4, y = 48.4 }, { name = "Alandien", area = 3520, x = 69.6, y = 54.1 } }, objective = "Larissa Sunstrike wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis. Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him. Return to Larissa Sunstrike with the Book of Fel Names after completing this task.  Completing quests for the Scryers will cause your Aldor reputation to decrease." },
    { id = 10702, name = "A Grunt's Work...", level = 69, minLevel = 67, faction = "Horde", giver = "Overlord Or'barokh", start = { npc = "Overlord Or'barokh", area = 3520, x = 28.4, y = 26.5 }, finish = { npc = "Overlord Or'barokh", area = 3520, x = 28.4, y = 26.5 }, steps = { { name = "Shadowmoon Valley Wildlife", area = 3520, x = 35.9, y = 43.4 } }, objective = "Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley wants you to kill 20 Shadowmoon Valley Wildlife.  These creatures include Felboars, Vilewing Chimaera, and Scorchshell Pincer. Any combination will be sufficient." },
    { id = 10703, name = "Put On Yer Kneepads...", level = 69, minLevel = 67, faction = "Alliance", giver = "Thane Yoregar", start = { npc = "Thane Yoregar", area = 3520, x = 36.2, y = 56.9 }, finish = { npc = "Thane Yoregar", area = 3520, x = 36.2, y = 56.9 }, steps = { { name = "Shadowmoon Valley Wildlife", area = 3520, x = 35.9, y = 43.4 } }, objective = "Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley wants you to kill 20 Shadowmoon Valley Wildlife.  These creatures include Felboars, Vilewing Chimaeras, and Scorchshell Pincers. Any combination will be sufficient." },
