    { id = 10751, name = "Breaching the Path", level = 70, minLevel = 68, requires = { 10750 }, faction = "Horde", giver = "Kor'kron Wind Rider", start = { npc = "Kor'kron Wind Rider", area = 3520, x = 51.2, y = 62.8 }, finish = { npc = "Kor'kron Wind Rider", area = 3520, x = 51.2, y = 62.8 }, steps = { { name = "Eclipsion Soldier", area = 3520, x = 52.6, y = 64.4 }, { name = "Eclipsion Cavalier", area = 3520, x = 52.6, y = 67.2 }, { name = "Eclipsion Spellbinder", area = 3520, x = 52.5, y = 64.2 } }, objective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 10 Eclipsion Spellbinders and then use the Kor'kron Flare Gun to signal another Kor'kron Wind Rider to report your task complete.  Speak with Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley should you lose your Kor'kron Flare Gun and require a replacement." },
